#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────


# Turns on "Sign in with GitHub" for the hosted Studio, on the linked Netlify
# site (constellation-sign-in). It covers what only the account owner can do:
# register the GitHub App, then give Netlify its client ID and client secret.
# The secret is typed into Netlify's own settings page, so it never passes
# through this script, a file, or a command line. Run it from the repository
# root with Git Bash (on Windows, `bash` in PowerShell is WSL, which can't run
# the Windows Netlify CLI):  bash scripts/setup-sign-in.sh

STUDIO_URL="https://mnichols08.github.io/constellation/"
STUDIO_ORIGIN="https://mnichols08.github.io"
EXCHANGE_URL="https://constellation-sign-in.netlify.app/api/github-exchange"
NETLIFY_ENV_PAGE="https://app.netlify.com/projects/constellation-sign-in/configuration/env"

# On Windows, `bash` typed in PowerShell or Command Prompt starts WSL's Linux
# bash. It can see the Windows `netlify` launcher but not Windows Node, so the
# CLI can't run there. Point at Git Bash instead, with its exact path if found.
if grep -qi microsoft /proc/version 2>/dev/null; then
  echo "This is WSL's Linux bash, which can't run the Windows Netlify CLI. Use Git Bash instead."
  git_exe=$(command -v git.exe 2>/dev/null || true)
  git_bash=""
  [[ -n "$git_exe" ]] && git_bash="$(dirname "$(dirname "$git_exe")")/bin/bash.exe"
  if [[ -n "$git_bash" && -f "$git_bash" ]] && command -v wslpath >/dev/null 2>&1; then
    echo "From PowerShell, in this folder, run:"
    echo "  & \"$(wslpath -w "$git_bash")\" scripts/setup-sign-in.sh"
  else
    echo "Open Git Bash in this folder and run:  bash scripts/setup-sign-in.sh"
  fi
  exit 1
fi

[[ -f .netlify/state.json ]] || { echo "Run this from the repository root (the folder linked to Netlify)."; exit 1; }
netlify --version >/dev/null 2>&1 || { echo "The Netlify CLI isn't working in this shell. Install it with: npm i -g netlify-cli"; exit 1; }
mkdir -p .netlify
ENV_FILE=".netlify/sign-in.env"   # gitignored; holds only the public client ID

# `netlify env:set` exits quietly without saving on the free plan, so public
# values go through the API instead.
SITE_ID=$(sed -n 's/.*"siteId": *"\([^"]*\)".*/\1/p' .netlify/state.json)
ACCOUNT_ID=$(netlify api getSite --data "{\"site_id\":\"$SITE_ID\"}" </dev/null 2>/dev/null | sed -n 's/^  "account_id": *"\([^"]*\)".*/\1/p')
[[ -n "$ACCOUNT_ID" ]] || { echo "Couldn't read the Netlify site. Run 'netlify login' and try again."; exit 1; }
IDS="\"account_id\":\"$ACCOUNT_ID\",\"site_id\":\"$SITE_ID\""

# netlify_put KEY VALUE stores a PUBLIC value for every deploy context. Never
# pass a secret: the value is part of a command line. Values here are URLs or
# a validated client ID, with no quotes or backslashes, so the JSON is safe.
netlify_put() {
  local key="$1" value="$2"
  netlify api deleteEnvVar --data "{$IDS,\"key\":\"$key\"}" </dev/null >/dev/null 2>&1 || true
  netlify api createEnvVars --data "{$IDS,\"body\":[{\"key\":\"$key\",\"values\":[{\"context\":\"all\",\"value\":\"$value\"}]}]}" </dev/null >/dev/null
  printf '  %s✓ set%s Netlify variable %s\n' "$GREEN" "$RESET" "$key"
}

# secret_state prints "ok" when GITHUB_CLIENT_SECRET is stored as a secret with
# a production value, otherwise a short reason. Netlify never returns secret
# values, and only the flags are read here.
secret_state() {
  local json scopes='"scopes":\[[^]]*"functions"'
  # Whitespace is dropped so the checks don't depend on the CLI's formatting.
  json=$(netlify api getEnvVar --data "{$IDS,\"key\":\"GITHUB_CLIENT_SECRET\"}" </dev/null 2>/dev/null | tr -d ' \t\r\n') || true
  if [[ "$json" != *'"key":"GITHUB_CLIENT_SECRET"'* ]]; then echo "it is not there yet"
  elif [[ "$json" != *'"is_secret":true'* ]]; then echo 'it is not marked "Contains secret values"'
  elif [[ "$json" != *'"context":"production"'* && "$json" != *'"context":"all"'* ]]; then echo "it has no Production value"
  elif ! [[ "$json" =~ $scopes ]]; then echo "its scopes leave out Functions"
  else echo ok
  fi
}

TOTAL_STAGES=4

banner "Constellation: Sign in with GitHub"

stage "Register the GitHub App"
say "GitHub opens a pre-filled 'Register new GitHub App' form."
open_url "https://github.com/settings/apps/new?name=Constellation%20Studio&description=Sign%20in%20to%20Constellation%20to%20map%20your%20pinned%20projects%20and%20languages.&url=https%3A%2F%2Fmnichols08.github.io%2Fconstellation%2F&callback_urls[]=https%3A%2F%2Fmnichols08.github.io%2Fconstellation%2F&public=true&webhook_active=false&request_oauth_on_install=false"
step "Check Callback URL is exactly $STUDIO_URL (with the trailing slash)."
step "Leave 'Expire user authorization tokens' ticked."
step "Leave 'Request user authorization during installation' and 'Enable Device Flow' unticked."
step "Webhook: leave 'Active' unticked."
step "Permissions: change nothing (every one stays 'No access')."
step "'Where can this GitHub App be installed?': choose 'Any account'."
step "Click 'Create GitHub App'."
note "If GitHub says the name is taken, change it to 'Constellation by mnichols08'."
note "People see this name on the GitHub consent screen."
pause "Press Enter once the app is created."

stage "Client ID"
say "You are now on the app's General page."
step "Under 'About', copy the Client ID (it starts with 'Iv')."
ask GITHUB_CLIENT_ID "Paste the Client ID:"
until [[ "$GITHUB_CLIENT_ID" =~ ^Iv[A-Za-z0-9.]{8,}$ ]]; do
  warn "That doesn't look like a Client ID (it starts with 'Iv'). Try again."
  ask GITHUB_CLIENT_ID "Paste the Client ID:"
done
write_env GITHUB_CLIENT_ID "$GITHUB_CLIENT_ID"
netlify_put GITHUB_CLIENT_ID "$GITHUB_CLIENT_ID"
netlify_put GITHUB_REDIRECT_URI "$STUDIO_URL"
netlify_put STUDIO_ORIGIN "$STUDIO_ORIGIN"
pause

stage "Client secret"
say "First, on the GitHub app page ('Client secrets' section):"
step "Click 'Generate a new client secret' and copy it right away (GitHub shows it once)."
say "Then, in Netlify's settings page that opens now:"
open_url "$NETLIFY_ENV_PAGE"
step "Choose 'Add a variable', then 'Add a single variable'."
step "Key: GITHUB_CLIENT_SECRET"
step "Tick 'Contains secret values'."
step "Scopes: choose specific scopes and include Functions (not Post processing)."
step "Deploy contexts: give it a value for Production, and paste the secret there."
step "Click 'Create variable'."
note "Already there from an earlier try? Use its 'Options' menu, then 'Edit', and paste the new secret."
note "The secret goes straight from your clipboard into Netlify; this script never sees it."
while true; do
  pause "Press Enter once the variable is created."
  state=$(secret_state)
  [[ "$state" == ok ]] && { printf '  %s✓ found%s GITHUB_CLIENT_SECRET, stored as a secret\n' "$GREEN" "$RESET"; break; }
  warn "Netlify's GITHUB_CLIENT_SECRET isn't right yet: $state."
  confirm "Fix it on the Netlify page and check again?" || { SKIPPED+=("Add GITHUB_CLIENT_SECRET as a secret at $NETLIFY_ENV_PAGE"); break; }
done

stage "Go live"
say "Netlify only picks up new variables on a fresh deploy."
if confirm "Deploy the sign-in function to production now?"; then
  netlify deploy --prod >/dev/null
  status=$(curl -s -o /dev/null -w '%{http_code}' -X OPTIONS -H "Origin: $STUDIO_ORIGIN" "$EXCHANGE_URL")
  if [[ "$status" == "204" ]]; then
    printf '  %s✓ live%s the sign-in function has its settings and is answering\n' "$GREEN" "$RESET"
  else
    warn "The function answered $status instead of 204. Check the variables at $NETLIFY_ENV_PAGE."
    SKIPPED+=("Check the Netlify environment variables, then: netlify deploy --prod")
  fi
else
  SKIPPED+=("Deploy: netlify deploy --prod")
fi
pause

finish
note "Client ID: $GITHUB_CLIENT_ID"
note "Tell Claude 'sign-in is set up' to switch the Sign in button on in the Studio."
printf '\n'
